"use strict";(globalThis.webpackChunkfiles_hub_docs=globalThis.webpackChunkfiles_hub_docs||[]).push([[9946],{3664(e){e.exports=JSON.parse('{"tag":{"label":"other-apps","permalink":"/tags/other-apps","allTagsPath":"/tags","count":6,"items":[{"id":"other-apps/access-keys","title":"Access keys (fh_usr_)","description":"Make an fh_usr_ access key for a script or server of yours, scoped to the projects and actions it needs. How long keys last, when FilesHub shows one again, rotating with a 24-hour overlap, and revoking.","permalink":"/other-apps/access-keys"},{"id":"other-apps/assistants","title":"Connect an AI assistant (MCP at /mcp/account)","description":"Add FilesHub to Claude, ChatGPT, Claude Code or Cursor with one address, https://fileshub.zaions.com/mcp/account. You approve each assistant on FilesHub, pick its projects and what it may do, and every delete it asks for waits for your yes.","permalink":"/other-apps/assistants"},{"id":"other-apps/index","title":"Other apps \u2014 your FilesHub projects in your own tools","description":"People who belong to FilesHub projects can connect their own scripts with fh_usr_ access keys, AI assistants over MCP, and servers with signed webhooks. What each door reaches, what it never reaches, and who switches it on.","permalink":"/other-apps"},{"id":"other-apps/api","title":"The person API (/api/account/v1)","description":"Every call of the FilesHub person API with curl examples \u2014 your account, projects, file metadata, 5-minute download links, deletes that wait for your yes, usage and limits, the email log without bodies, and your webhooks. One envelope, cursor pages, an OpenAPI 3.1 file.","permalink":"/other-apps/api"},{"id":"other-apps/two-step-sign-in","title":"Two-step sign-in for people","description":"Turn on two-step sign-in on FilesHub with an authenticator app and ten recovery codes. Remembered browsers, what a recovery code can and cannot do, moving to a new phone, signing out everywhere else, and a support reset.","permalink":"/other-apps/two-step-sign-in"},{"id":"other-apps/webhooks","title":"Webhooks \u2014 events, signatures and retries","description":"FilesHub sends your server a signed POST when a file is uploaded or deleted, an email is sent or fails, or a service passes 80% of its limit. Sample payloads for every event, Standard Webhooks verification in Node and PHP, retries, pausing and the addresses FilesHub refuses.","permalink":"/other-apps/webhooks"}],"unlisted":false}}')}}]);